// Rango que manda el dashboard. Sin fechas = mes en curso.
const ahora = new Date();
const inicioMes = new Date(ahora.getFullYear(), ahora.getMonth(), 1);
let desde = Math.floor(inicioMes.getTime() / 1000);
let hasta = Math.floor(ahora.getTime() / 1000);

try {
  const q = $('Webhook Empeños').first().json.query || {};
  if (q.desde && q.hasta) { desde = Number(q.desde); hasta = Number(q.hasta); }
  else { desde = 0; hasta = Math.floor(Date.now() / 1000); }
} catch (e) { /* ejecución manual: mes en curso */ }

// Kommo NO permite filtrar por el campo F_Empeño en esta cuenta
// ("Invalid filter for current account"), así que se filtra por updated_at:
// un lead empeñado dentro del rango se actualizó forzosamente dentro del rango.
// El margen cubre relojes desfasados y ediciones con fecha retroactiva.
const MARGEN_DIAS = 2;
const desdeUpd = Math.max(0, desde - MARGEN_DIAS * 86400);

return [{ json: { desde, hasta, desdeUpd, page: 1 } }];

const raw = $input.first().json;
const resp = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw;
const leads = resp._embedded?.leads || [];

const sd = $getWorkflowStaticData('global');
if (!sd.empLeads) sd.empLeads = [];
if (!sd.empPage) sd.empPage = 1;

sd.empLeads = sd.empLeads.concat(leads);
sd.empPage += 1;

return [{ json: { hasMore: leads.length === 250, page: sd.empPage, total: sd.empLeads.length } }];

// F_Empeño = campo 1380934 (date_time). Se filtra AQUÍ por el rango exacto:
// la consulta a Kommo fue por updated_at, que es más amplio.
const F_EMPENO_FIELD_ID = 1380934;

const { desde, hasta } = $('Lee Rango Empeños').first().json;
const sd = $getWorkflowStaticData('global');
const leads = sd.empLeads || [];
sd.empLeads = [];
sd.empPage = 1;

const tsDe = (lead) => {
  const f = (lead.custom_fields_values || []).find(c => c.field_id === F_EMPENO_FIELD_ID);
  return Number(f?.values?.[0]?.value) || 0;
};

const enRango = leads.filter(l => { const ts = tsDe(l); return ts >= desde && ts <= hasta; });

const detalle = enRango.map(l => {
  const ts = tsDe(l);
  return {
    id_lead: l.id,
    nombre: l._embedded?.contacts?.[0]?.name || l.name,
    precio: l.price || 0,
    f_empeno_ts: ts,
    f_empeno: new Date(ts * 1000).toLocaleString('es-MX', { timeZone: 'America/Mexico_City' }),
    fecha_creacion: new Date(l.created_at * 1000).toLocaleString('es-MX', { timeZone: 'America/Mexico_City' })
  };
});

return [{ json: {
  total: detalle.length,
  monto: detalle.reduce((a, d) => a + Number(d.precio || 0), 0),
  rango: { desde, hasta },
  revisados: leads.length,
  leads: detalle
} }];
